{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.12","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"nvidiaTeslaT4","dataSources":[],"dockerImageVersionId":31329,"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":true}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:23:48.285790Z\",\"iopub.execute_input\":\"2026-04-02T20:23:48.286068Z\",\"iopub.status.idle\":\"2026-04-02T20:23:54.785309Z\",\"shell.execute_reply.started\":\"2026-04-02T20:23:48.286031Z\",\"shell.execute_reply\":\"2026-04-02T20:23:54.784203Z\"}}\n!pip install -q transformers peft wandb torchvision matplotlib pandas\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:24:43.101670Z\",\"iopub.execute_input\":\"2026-04-02T20:24:43.102552Z\",\"iopub.status.idle\":\"2026-04-02T20:25:21.084040Z\",\"shell.execute_reply.started\":\"2026-04-02T20:24:43.102500Z\",\"shell.execute_reply\":\"2026-04-02T20:25:21.083410Z\"}}\nimport torch\nimport torch.nn as nn\nimport torch.optim as optim\nimport torchvision\nimport torchvision.transforms as transforms\nfrom torch.utils.data import DataLoader\nfrom transformers import ViTForImageClassification\nfrom peft import LoraConfig, get_peft_model\nimport wandb\nimport pandas as pd\nimport matplotlib.pyplot as plt\nimport os\n\nos.makedirs(\"weights\", exist_ok=True)\nos.makedirs(\"results\", exist_ok=True)\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:25:28.987106Z\",\"iopub.execute_input\":\"2026-04-02T20:25:28.987484Z\",\"iopub.status.idle\":\"2026-04-02T20:25:28.992203Z\",\"shell.execute_reply.started\":\"2026-04-02T20:25:28.987453Z\",\"shell.execute_reply\":\"2026-04-02T20:25:28.991330Z\"}}\nDEVICE = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\nBATCH_SIZE = 64\nEPOCHS = 5 # Adjust based on your compute limits\nNUM_CLASSES = 100\nMODEL_NAME = \"google/vit-base-patch16-224-in21k\"\nDROPOUT = 0.1\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:25:31.335692Z\",\"iopub.execute_input\":\"2026-04-02T20:25:31.336466Z\",\"iopub.status.idle\":\"2026-04-02T20:25:31.342016Z\",\"shell.execute_reply.started\":\"2026-04-02T20:25:31.336429Z\",\"shell.execute_reply\":\"2026-04-02T20:25:31.341274Z\"}}\ndef get_dataloaders():\n    transform = transforms.Compose([\n        transforms.Resize((224, 224)),\n        transforms.ToTensor(),\n        transforms.Normalize(mean=[0.5, 0.5, 0.5], std=[0.5, 0.5, 0.5])\n    ])\n    trainset = torchvision.datasets.CIFAR100(root='./data', train=True, download=True, transform=transform)\n    testset = torchvision.datasets.CIFAR100(root='./data', train=False, download=True, transform=transform)\n    trainloader = DataLoader(trainset, batch_size=BATCH_SIZE, shuffle=True, num_workers=2)\n    testloader = DataLoader(testset, batch_size=BATCH_SIZE, shuffle=False, num_workers=2)\n    return trainloader, testloader, testset.classes\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:25:41.171818Z\",\"iopub.execute_input\":\"2026-04-02T20:25:41.172595Z\",\"iopub.status.idle\":\"2026-04-02T20:25:41.182891Z\",\"shell.execute_reply.started\":\"2026-04-02T20:25:41.172563Z\",\"shell.execute_reply\":\"2026-04-02T20:25:41.182203Z\"}}\ndef train_epoch(model, dataloader, criterion, optimizer):\n    model.train()\n    running_loss, correct, total = 0.0, 0, 0\n    for inputs, labels in dataloader:\n        inputs, labels = inputs.to(DEVICE), labels.to(DEVICE)\n        optimizer.zero_grad()\n        outputs = model(inputs).logits\n        loss = criterion(outputs, labels)\n        loss.backward()\n        optimizer.step()\n        running_loss += loss.item()\n        _, predicted = outputs.max(1)\n        total += labels.size(0)\n        correct += predicted.eq(labels).sum().item()\n    return running_loss / len(dataloader), 100. * correct / total\n\ndef eval_model_classwise(model, dataloader, criterion):\n    model.eval()\n    running_loss, correct, total = 0.0, 0, 0\n    class_correct = list(0. for i in range(100))\n    class_total = list(0. for i in range(100))\n    \n    with torch.no_grad():\n        for inputs, labels in dataloader:\n            inputs, labels = inputs.to(DEVICE), labels.to(DEVICE)\n            outputs = model(inputs).logits\n            loss = criterion(outputs, labels)\n            running_loss += loss.item()\n            _, predicted = outputs.max(1)\n            total += labels.size(0)\n            correct += predicted.eq(labels).sum().item()\n            \n            c = (predicted == labels).squeeze()\n            for i in range(len(labels)):\n                label = labels[i]\n                class_correct[label] += c[i].item()\n                class_total[label] += 1\n                \n    overall_acc = 100. * correct / total\n    overall_loss = running_loss / len(dataloader)\n    class_accuracies = [100 * class_correct[i] / class_total[i] if class_total[i] > 0 else 0 for i in range(100)]\n    return overall_loss, overall_acc, class_accuracies\n\ndef get_trainable_params(model):\n    return sum(p.numel() for p in model.parameters() if p.requires_grad), sum(p.numel() for p in model.parameters())\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:25:44.187565Z\",\"iopub.execute_input\":\"2026-04-02T20:25:44.188341Z\",\"iopub.status.idle\":\"2026-04-02T20:25:44.193336Z\",\"shell.execute_reply.started\":\"2026-04-02T20:25:44.188310Z\",\"shell.execute_reply\":\"2026-04-02T20:25:44.192586Z\"}}\ndef plot_class_histogram(class_accuracies, classes, filename):\n    plt.figure(figsize=(20, 8))\n    plt.bar(classes[:50], class_accuracies[:50], color='skyblue')\n    plt.xlabel('CIFAR-100 Classes', fontsize=12)\n    plt.ylabel('Test Accuracy (%)', fontsize=12)\n    plt.title('Class-wise Test Accuracy Histogram', fontsize=16)\n    plt.xticks(rotation=90)\n    plt.tight_layout()\n    plt.savefig(f'results/{filename}.png')\n    plt.close()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:25:47.059800Z\",\"iopub.execute_input\":\"2026-04-02T20:25:47.060398Z\",\"iopub.status.idle\":\"2026-04-02T20:25:47.070304Z\",\"shell.execute_reply.started\":\"2026-04-02T20:25:47.060360Z\",\"shell.execute_reply\":\"2026-04-02T20:25:47.069448Z\"}}\ndef run_all_experiments():\n    trainloader, testloader, classes = get_dataloaders()\n    ranks = [2, 4, 8]\n    alphas = [2, 4, 8]\n    results_table = []\n    \n    for r in ranks:\n        for alpha in alphas:\n            experiment_name = f\"LoRA_Rank{r}_Alpha{alpha}\"\n            print(f\"\\n========== Starting {experiment_name} ==========\")\n            \n            wandb.init(project=\"DL_Assignment_Q1\", name=experiment_name, reinit=True)\n            \n            model = ViTForImageClassification.from_pretrained(MODEL_NAME, num_labels=NUM_CLASSES, ignore_mismatched_sizes=True)\n            config = LoraConfig(r=r, lora_alpha=alpha, target_modules=[\"query\", \"key\", \"value\"], lora_dropout=DROPOUT, bias=\"none\", modules_to_save=[\"classifier\"])\n            model = get_peft_model(model, config).to(DEVICE)\n            \n            trainable_params, _ = get_trainable_params(model)\n            wandb.watch(model, log=\"gradients\", log_freq=10)\n            \n            criterion = nn.CrossEntropyLoss()\n            optimizer = optim.AdamW(model.parameters(), lr=1e-3)\n            epoch_table = []\n            \n            for epoch in range(1, EPOCHS + 1):\n                train_loss, train_acc = train_epoch(model, trainloader, criterion, optimizer)\n                val_loss, val_acc, class_accs = eval_model_classwise(model, testloader, criterion)\n                print(f\"Epoch {epoch}/{EPOCHS} | Train Acc: {train_acc:.2f}% | Val Acc: {val_acc:.2f}%\")\n                \n                wandb.log({\"epoch\": epoch, \"train_loss\": train_loss, \"val_loss\": val_loss, \"train_acc\": train_acc, \"val_acc\": val_acc})\n                epoch_table.append({\"Epoch\": epoch, \"Train Loss\": train_loss, \"Val Loss\": val_loss, \"Train Acc\": train_acc, \"Val Acc\": val_acc})\n            \n            model.save_pretrained(f\"weights/q1_{experiment_name}\")\n            plot_class_histogram(class_accs, classes, f\"histogram_{experiment_name}\")\n            \n            results_table.append({\"Rank\": r, \"Alpha\": alpha, \"Overall Test Accuracy\": val_acc, \"Trainable Parameters\": trainable_params})\n            \n            print(f\"\\n--- EPOCH TABLE for {experiment_name} ---\")\n            print(pd.DataFrame(epoch_table).to_markdown(index=False))\n            wandb.finish()\n            \n    print(\"\\n--- FINAL RESULTS TABLE (ALL COMBINATIONS) ---\")\n    print(pd.DataFrame(results_table).to_markdown(index=False))\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:27:19.025790Z\",\"iopub.execute_input\":\"2026-04-02T20:27:19.026614Z\",\"iopub.status.idle\":\"2026-04-02T20:28:52.606733Z\",\"shell.execute_reply.started\":\"2026-04-02T20:27:19.026577Z\",\"shell.execute_reply\":\"2026-04-02T20:28:52.605909Z\"}}\nimport wandb\nwandb.login()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-02T20:28:59.299802Z\",\"iopub.execute_input\":\"2026-04-02T20:28:59.300410Z\",\"iopub.status.idle\":\"2026-04-03T03:24:15.646539Z\",\"shell.execute_reply.started\":\"2026-04-02T20:28:59.300374Z\",\"shell.execute_reply\":\"2026-04-03T03:24:15.644001Z\"}}\nif __name__ == \"__main__\":\n    # import wandb\n    # wandb.login(key=\"YOUR_KEY\")\n    run_all_experiments()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-03T03:29:51.803965Z\",\"iopub.execute_input\":\"2026-04-03T03:29:51.804720Z\",\"execution_failed\":\"2026-04-03T08:23:46.678Z\"}}\n# --- THE COMPLETION SCRIPT ---\n# Run this cell to finish the missing Q1 requirements without re-running Rank 2.\n\ndef run_baseline_no_lora():\n    print(\"\\n========== Starting Baseline (No LoRA) ==========\")\n    trainloader, testloader, classes = get_dataloaders()\n    \n    wandb.init(project=\"DL_Assignment_Q1\", name=\"Baseline_No_LoRA\", reinit=True)\n    \n    # Load Model\n    model = ViTForImageClassification.from_pretrained(\n        MODEL_NAME, num_labels=NUM_CLASSES, ignore_mismatched_sizes=True\n    )\n    model = model.to(DEVICE)\n    \n    # FREEZE the base model, ONLY train the classifier head\n    for name, param in model.named_parameters():\n        if \"classifier\" not in name:\n            param.requires_grad = False\n            \n    trainable_params, total_params = get_trainable_params(model)\n    print(f\"Baseline Trainable Params: {trainable_params} / {total_params}\")\n    \n    criterion = nn.CrossEntropyLoss()\n    optimizer = optim.AdamW(model.parameters(), lr=1e-3)\n    \n    for epoch in range(1, EPOCHS + 1):\n        train_loss, train_acc = train_epoch(model, trainloader, criterion, optimizer)\n        val_loss, val_acc, class_accs = eval_model_classwise(model, testloader, criterion)\n        print(f\"Epoch {epoch}/{EPOCHS} | Train Acc: {train_acc:.2f}% | Val Acc: {val_acc:.2f}%\")\n        wandb.log({\"epoch\": epoch, \"train_loss\": train_loss, \"val_loss\": val_loss, \"train_acc\": train_acc, \"val_acc\": val_acc})\n        \n    model.save_pretrained(\"weights/q1_Baseline_No_LoRA\")\n    plot_class_histogram(class_accs, classes, \"histogram_Baseline_No_LoRA\")\n    wandb.finish()\n\n\ndef run_remaining_lora_grid():\n    trainloader, testloader, classes = get_dataloaders()\n    \n    # ONLY running the missing ranks (4 and 8)\n    missing_ranks = [4, 8]\n    alphas = [2, 4, 8]\n    \n    for r in missing_ranks:\n        for alpha in alphas:\n            experiment_name = f\"LoRA_Rank{r}_Alpha{alpha}\"\n            print(f\"\\n========== Starting {experiment_name} ==========\")\n            \n            wandb.init(project=\"DL_Assignment_Q1\", name=experiment_name, reinit=True)\n            \n            model = ViTForImageClassification.from_pretrained(MODEL_NAME, num_labels=NUM_CLASSES, ignore_mismatched_sizes=True)\n            config = LoraConfig(r=r, lora_alpha=alpha, target_modules=[\"query\", \"key\", \"value\"], lora_dropout=DROPOUT, bias=\"none\", modules_to_save=[\"classifier\"])\n            model = get_peft_model(model, config).to(DEVICE)\n            \n            wandb.watch(model, log=\"gradients\", log_freq=10)\n            \n            criterion = nn.CrossEntropyLoss()\n            optimizer = optim.AdamW(model.parameters(), lr=1e-3)\n            \n            for epoch in range(1, EPOCHS + 1):\n                train_loss, train_acc = train_epoch(model, trainloader, criterion, optimizer)\n                val_loss, val_acc, class_accs = eval_model_classwise(model, testloader, criterion)\n                print(f\"Epoch {epoch}/{EPOCHS} | Train Acc: {train_acc:.2f}% | Val Acc: {val_acc:.2f}%\")\n                wandb.log({\"epoch\": epoch, \"train_loss\": train_loss, \"val_loss\": val_loss, \"train_acc\": train_acc, \"val_acc\": val_acc})\n            \n            model.save_pretrained(f\"weights/q1_{experiment_name}\")\n            plot_class_histogram(class_accs, classes, f\"histogram_{experiment_name}\")\n            wandb.finish()\n\n# Execute both missing parts\nrun_baseline_no_lora()\nrun_remaining_lora_grid()\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-03T03:24:15.649336Z\",\"iopub.status.idle\":\"2026-04-03T03:24:15.649810Z\",\"shell.execute_reply.started\":\"2026-04-03T03:24:15.649547Z\",\"shell.execute_reply\":\"2026-04-03T03:24:15.649577Z\"}}\n!pip install -q transformers peft optuna wandb torchvision\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-03T03:24:15.653513Z\",\"iopub.status.idle\":\"2026-04-03T03:24:15.653793Z\",\"shell.execute_reply.started\":\"2026-04-03T03:24:15.653658Z\",\"shell.execute_reply\":\"2026-04-03T03:24:15.653675Z\"}}\nimport torch\nimport torch.nn as nn\nimport torch.optim as optim\nimport torchvision\nimport torchvision.transforms as transforms\nfrom torch.utils.data import DataLoader\nfrom transformers import ViTForImageClassification\nfrom peft import LoraConfig, get_peft_model\nimport optuna\nimport os\n\nDEVICE = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\nBATCH_SIZE = 64\nEPOCHS = 3 # Keep epochs low for Optuna to save time\nNUM_CLASSES = 100\nMODEL_NAME = \"google/vit-base-patch16-224-in21k\"\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-03T03:24:15.655377Z\",\"iopub.status.idle\":\"2026-04-03T03:24:15.655694Z\",\"shell.execute_reply.started\":\"2026-04-03T03:24:15.655531Z\",\"shell.execute_reply\":\"2026-04-03T03:24:15.655547Z\"}}\ndef get_dataloaders():\n    transform = transforms.Compose([\n        transforms.Resize((224, 224)),\n        transforms.ToTensor(),\n        transforms.Normalize(mean=[0.5, 0.5, 0.5], std=[0.5, 0.5, 0.5])\n    ])\n    trainset = torchvision.datasets.CIFAR100(root='./data', train=True, download=True, transform=transform)\n    testset = torchvision.datasets.CIFAR100(root='./data', train=False, download=True, transform=transform)\n    trainloader = DataLoader(trainset, batch_size=BATCH_SIZE, shuffle=True, num_workers=2)\n    testloader = DataLoader(testset, batch_size=BATCH_SIZE, shuffle=False, num_workers=2)\n    return trainloader, testloader\n\ndef train_and_eval(model, trainloader, testloader):\n    criterion = nn.CrossEntropyLoss()\n    optimizer = optim.AdamW(model.parameters(), lr=1e-3)\n    \n    for epoch in range(EPOCHS):\n        model.train()\n        for inputs, labels in trainloader:\n            inputs, labels = inputs.to(DEVICE), labels.to(DEVICE)\n            optimizer.zero_grad()\n            outputs = model(inputs).logits\n            loss = criterion(outputs, labels)\n            loss.backward()\n            optimizer.step()\n            \n    model.eval()\n    correct, total = 0, 0\n    with torch.no_grad():\n        for inputs, labels in testloader:\n            inputs, labels = inputs.to(DEVICE), labels.to(DEVICE)\n            outputs = model(inputs).logits\n            _, predicted = outputs.max(1)\n            total += labels.size(0)\n            correct += predicted.eq(labels).sum().item()\n            \n    return 100. * correct / total\n\n# %% [code] {\"execution\":{\"iopub.status.busy\":\"2026-04-03T03:24:15.971626Z\",\"iopub.execute_input\":\"2026-04-03T03:24:15.972315Z\",\"iopub.status.idle\":\"2026-04-03T03:24:15.983773Z\",\"shell.execute_reply.started\":\"2026-04-03T03:24:15.972275Z\",\"shell.execute_reply\":\"2026-04-03T03:24:15.982694Z\"}}\ndef objective(trial):\n    trainloader, testloader = get_dataloaders()\n    \n    # Let Optuna pick the hyperparameters\n    r = trial.suggest_categorical(\"r\", [2, 4, 8])\n    alpha = trial.suggest_categorical(\"alpha\", [2, 4, 8])\n    \n    print(f\"\\n--- Optuna Trial: Rank {r}, Alpha {alpha} ---\")\n    \n    model = ViTForImageClassification.from_pretrained(MODEL_NAME, num_labels=NUM_CLASSES, ignore_mismatched_sizes=True)\n    config = LoraConfig(r=r, lora_alpha=alpha, target_modules=[\"query\", \"key\", \"value\"], lora_dropout=0.1, bias=\"none\", modules_to_save=[\"classifier\"])\n    model = get_peft_model(model, config).to(DEVICE)\n    \n    accuracy = train_and_eval(model, trainloader, testloader)\n    return accuracy\n\nif __name__ == \"__main__\":\n    study = optuna.create_study(direction=\"maximize\")\n    study.optimize(objective, n_trials=5) # Run 5 random combinations\n    \n    print(\"\\n=== OPTUNA OPTIMIZATION COMPLETE ===\")\n    print(\"Best Trial:\")\n    print(\"  Value (Accuracy): \", study.best_trial.value)\n    print(\"  Best Hyperparameters: \", study.best_trial.params)","metadata":{"_uuid":"99db416a-c881-4c98-b49d-59475acb7dba","_cell_guid":"00352c17-017a-427b-8d91-fca2f09d70f9","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false}},"outputs":[],"execution_count":null}]}